retry(i int, handler func() bool)  doc:retry 对第二个参数作为函数的情况，重试N次，如果第二个参数返回值是 true，则重试，否则就结束，如果遇到错误，停止重试

Example:
```
count = 0

	retry(100, () => {
	   defer recover()

	   count++
	   if count > 3 {
	       die(111)
	   }
	   return true
	})

assert count == 4, f`${count}`

count = 0

	retry(100, () => {
	   defer recover()

	   count++
	   if count > 3 {
	       return false
	   }
	   return true
	})

assert count == 4, f`${count}`

count = 0

	retry(100, () => {
	   count++
	})

assert count == 1, f`${count}`

count = 0

	retry(100, () => {
	   count++
	   return true
	})

assert count == 100, f`${count}`
```

